mapper.select:
SELECT 
FROM study_weekly_report
WHERE user_id = #{userId}
  AND week_start = #{weekStart}

mapper.update:
UPDATE study_weekly_report
SET week_end = #{weekEnd},
    completion_rate = #{completionRate},
    study_minutes = #{studyMinutes},
    chat_questions = #{chatQuestions},
    weak_subjects_json = #{weakSubjects, typeHandler=com.group4.kaoyan.common.mybatis.JsonTypeHandler},
    next_actions_json = #{nextActions, typeHandler=com.group4.kaoyan.common.mybatis.JsonTypeHandler},
    summary = #{summary},
    generated_at = #{generatedAt},
    update_time = #{updateTime}
WHERE id = #{id}
  AND user_id = #{userId}
  AND week_start = #{weekStart}
